import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';

const ProblemList = () => {
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterDifficulty, setFilterDifficulty] = useState('All');
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/problems`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  const getDifficultyColor = (difficulty) => {
    switch (difficulty) {
      case 'Easy': return '#28a745';
      case 'Medium': return '#ffc107';
      case 'Hard': return '#dc3545';
      default: return '#6c757d';
    }
  };

  const filteredProblems = problems.filter(problem => {
    const matchesSearch = problem.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDifficulty = filterDifficulty === 'All' || problem.difficulty === filterDifficulty;
    return matchesSearch && matchesDifficulty;
  });

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div className="loading-spinner"></div>
        <p>Loading problems...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Navigation */}
      <nav style={styles.nav}>
        <div style={styles.navLeft}>
          <h1 style={styles.logo}>⚡ CodeArena</h1>
          <span style={styles.navSubtitle}>Problems</span>
        </div>
        <div style={styles.navRight}>
          <button onClick={() => navigate('/')} style={styles.navButton}>
            🏠 Dashboard
          </button>
          <button onClick={() => navigate('/submissions')} style={styles.navButton}>
            📊 Submissions
          </button>
        </div>
      </nav>

      {/* Header */}
      <div style={styles.header}>
        <h1 style={styles.title}>📚 Problems</h1>
        <p style={styles.subtitle}>Solve problems and improve your coding skills</p>
      </div>

      {/* Filters */}
      <div style={styles.filters}>
        <div style={styles.searchBox}>
          <input
            type="text"
            placeholder="🔍 Search problems..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={styles.searchInput}
          />
        </div>
        <div style={styles.filterButtons}>
          {['All', 'Easy', 'Medium', 'Hard'].map(difficulty => (
            <button
              key={difficulty}
              onClick={() => setFilterDifficulty(difficulty)}
              style={{
                ...styles.filterButton,
                ...(filterDifficulty === difficulty ? styles.filterButtonActive : {})
              }}
            >
              {difficulty}
            </button>
          ))}
        </div>
      </div>

      {/* Problem Grid */}
      <div style={styles.grid}>
        {filteredProblems.length === 0 ? (
          <div style={styles.emptyState}>
            <p style={styles.emptyIcon}>🔍</p>
            <h3>No problems found</h3>
            <p>Try adjusting your search or filters</p>
          </div>
        ) : (
          filteredProblems.map(problem => (
            <div
              key={problem._id}
              style={styles.card}
              onClick={() => navigate(`/problems/${problem._id}`)}
            >
              <div style={styles.cardHeader}>
                <h3 style={styles.cardTitle}>{problem.title}</h3>
                <span style={{
                  ...styles.difficultyBadge,
                  backgroundColor: getDifficultyColor(problem.difficulty)
                }}>
                  {problem.difficulty || 'Easy'}
                </span>
              </div>
              <p style={styles.cardDescription}>
                {problem.description?.substring(0, 120)}...
              </p>
              <div style={styles.cardFooter}>
                <span style={styles.cardDate}>
                  📅 {new Date(problem.createdAt).toLocaleDateString()}
                </span>
                <span style={styles.cardAction}>▶ Solve</span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f7fa'
  },
  nav: {
    background: 'white',
    padding: '15px 30px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)',
    position: 'sticky',
    top: 0,
    zIndex: 100
  },
  navLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '15px'
  },
  logo: {
    color: '#1a73e8',
    fontSize: '24px',
    margin: 0
  },
  navSubtitle: {
    color: '#666',
    fontSize: '16px'
  },
  navRight: {
    display: 'flex',
    gap: '10px'
  },
  navButton: {
    padding: '8px 16px',
    background: '#f0f2f5',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '14px'
  },
  header: {
    padding: '30px 40px',
    background: 'white',
    margin: '20px 20px 0 20px',
    borderRadius: '12px 12px 0 0',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)'
  },
  title: {
    fontSize: '28px',
    marginBottom: '5px'
  },
  subtitle: {
    color: '#666',
    fontSize: '14px'
  },
  filters: {
    background: 'white',
    padding: '15px 20px',
    margin: '0 20px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    borderBottom: '1px solid #e9ecef',
    flexWrap: 'wrap',
    gap: '10px'
  },
  searchBox: {
    flex: '1',
    minWidth: '200px'
  },
  searchInput: {
    width: '100%',
    padding: '10px 15px',
    border: '2px solid #e1e5e9',
    borderRadius: '8px',
    fontSize: '14px'
  },
  filterButtons: {
    display: 'flex',
    gap: '8px',
    flexWrap: 'wrap'
  },
  filterButton: {
    padding: '6px 16px',
    border: '2px solid #e1e5e9',
    borderRadius: '20px',
    background: 'white',
    cursor: 'pointer',
    fontSize: '13px',
    transition: 'all 0.3s'
  },
  filterButtonActive: {
    background: '#1a73e8',
    color: 'white',
    borderColor: '#1a73e8'
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
    gap: '20px',
    padding: '20px',
    maxWidth: '1400px',
    margin: '0 auto'
  },
  card: {
    background: 'white',
    padding: '20px',
    borderRadius: '12px',
    boxShadow: '0 2px 4px rgba(0,0,0,0.08)',
    cursor: 'pointer',
    transition: 'transform 0.3s, box-shadow 0.3s',
    display: 'flex',
    flexDirection: 'column',
    gap: '12px'
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start'
  },
  cardTitle: {
    fontSize: '18px',
    margin: 0,
    flex: 1,
    marginRight: '10px'
  },
  difficultyBadge: {
    padding: '4px 12px',
    borderRadius: '20px',
    color: 'white',
    fontSize: '12px',
    fontWeight: '600',
    whiteSpace: 'nowrap'
  },
  cardDescription: {
    color: '#666',
    fontSize: '14px',
    lineHeight: '1.5',
    margin: 0
  },
  cardFooter: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginTop: '5px',
    paddingTop: '12px',
    borderTop: '1px solid #e9ecef'
  },
  cardDate: {
    color: '#999',
    fontSize: '12px'
  },
  cardAction: {
    color: '#1a73e8',
    fontWeight: '600',
    fontSize: '14px'
  },
  loadingContainer: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh'
  },
  emptyState: {
    gridColumn: '1 / -1',
    textAlign: 'center',
    padding: '60px 20px',
    background: 'white',
    borderRadius: '12px'
  },
  emptyIcon: {
    fontSize: '48px',
    marginBottom: '10px'
  }
};

export default ProblemList;
